function serializeQuestion(number, question) {
  const fields = {skill_tested: question.skill_tested, question: question.question};
  question.options.forEach((option, index) => { fields[`option${index + 1}`] = option; });
  Object.assign(fields, {correctAnswer: question.correctAnswer, explanation: question.explanation, practiceYear: question.practiceYear, difficulty: question.difficulty, module: question.module, imageSources: [], passage: "{{shared_passage}}"});
  return `${number}: {${Object.entries(fields).map(([key, value]) => `${key}: ${JSON.stringify(value)}`).join(", ")}}`;
}

for (const item of replacements) {
  const sourceFolder = path.join(root, "work", `source-${String(item.source).padStart(2, "0")}`);
  const folder = path.join(sourceFolder, `blueprint-${item.blueprint.toLowerCase()}`);
  item.passage += extensions[`${item.source}${item.blueprint}`] || "";
  if (item.source === 8 && item.blueprint === "A") {
    item.passage = item.passage.replace("<b>LITERARY NARRATIVE:</b> This passage is from a story about a teenager helping during an apartment-building water outage.", "<b>LITERARY NARRATIVE:</b> In the selection below, a teenager helps during an apartment-building water outage.");
  }
  const wordCount = countWords(item.passage);
  if (wordCount < 650 || wordCount > 850) throw new Error(`${item.source}${item.blueprint} has ${wordCount} words.`);
  if (item.questions.length !== 9) throw new Error(`${item.source}${item.blueprint} does not have nine questions.`);
  const passage = {
    passage_asset_id: `act-reading-s${String(item.source).padStart(2, "0")}-${item.blueprint.toLowerCase()}`,
    act_reading_passage_type: item.type,
    passage_type_display_label: item.type.toUpperCase(),
    passage_title: item.title,
    passage: item.passage,
    imageSources: [],
    passage_word_count: wordCount,
    paragraphs: [],
    originality_notes: [item.distinctness, "Independently composed for this replacement audit."],
    passage_quality_self_check: {correct_passage_type_header: true, word_count_in_target_range: true, supports_at_least_two_very_hard_questions: true, requires_no_outside_knowledge: true, text_only_asset: true, mobile_formatting_ready: true, copyright_safe: true},
  };
  fs.writeFileSync(path.join(folder, "passage.json"), `${JSON.stringify(passage, null, 2)}\n`);
  const fragment = `{\n${item.questions.map((question, index) => serializeQuestion(item.start + index, question)).join(",\n")}\n}\n`;
  fs.writeFileSync(path.join(folder, "final.jsfrag"), fragment);
  fs.writeFileSync(path.join(folder, "questions.jsfrag"), fragment);
  const blueprintFile = path.join(sourceFolder, "blueprints.json");
  const blueprintData = JSON.parse(fs.readFileSync(blueprintFile, "utf8"));
  const blueprint = blueprintData.blueprints.find((candidate) => candidate.blueprint_label === item.blueprint);
  blueprint.blueprint_focus = item.focus;
  blueprint.act_reading_passage_type = item.type;
  blueprint.distinctness_notes = item.distinctness;
  fs.writeFileSync(blueprintFile, `${JSON.stringify(blueprintData, null, 2)}\n`);
  console.log(`Replaced S${item.source}${item.blueprint}, questions ${item.start}-${item.start + 8}, ${wordCount} words.`);
}
